-- Supabase/Postgres starter schema
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, plan text not null default 'free', created_at timestamptz not null default now());
create table if not exists conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'New chat', created_at timestamptz not null default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references conversations(id) on delete cascade, role text not null, content text not null, created_at timestamptz not null default now());
create table if not exists subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, provider text not null, provider_ref text, plan text not null, status text not null, current_period_end timestamptz, created_at timestamptz not null default now());
create table if not exists payments (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete set null, provider text not null, provider_txn_id text, amount numeric(12,2) not null, currency text not null, status text not null, raw_event jsonb, created_at timestamptz not null default now());
create table if not exists usage (user_id uuid primary key references auth.users(id) on delete cascade, period_start date not null, messages_count integer not null default 0, agent_runs integer not null default 0, updated_at timestamptz not null default now());
